from lib import *
S = SS('n39')
steps = [
    step("Static(path, root) 就是 StaticFS(path, Dir(root, false)),注册 GET 与 HEAD 的 path/*filepath。handler 里:如果文件系统是 OnlyFilesFS(不列目录),先 c.Writer.WriteHeader(404)(只是记录状态);然后 fs.Open(file) 打不开就把 handler 链换成 noRoute 并返回;打得开就交给 http.StripPrefix + http.FileServer。Dir(root, false) 返回的 OnlyFilesFS 把 Readdir 改成永远返回 nil——禁止列目录。", t=tl(S(1)), mark=lidx(S(1), 'c.Writer.WriteHeader(http.StatusNotFound)', 'c.handlers = group.engine.noRoute', 'OnlyFilesFS'), done=lidx(S(1), 'http.StripPrefix(absolutePath, http.FileServer(fs))', 'if listDirectory {'), kv=KV([['Static', 'StaticFS + Dir(root, false)'], ['打不开', '走 NoRoute'], ['不列目录', 'Readdir 恒返回 nil']], ['不列目录'])),
    step("Static(\"/static\", \"site/public\") 对各种请求(原始 TCP):文件 200;/static/ 目录里有 index.html → 200 返回它;/static/index.html → 301 Location: ./;没有 index 的目录 /static/sub/ → 404,而且正文是个空的目录列表页;/static/sub 少斜杠 → 301 到 sub/;不存在的 → 404;/static/.env(点文件)→ 200,内容被直接返回;/static/link.txt 是指向根目录之外 ../secret.txt 的符号链接 → 200,内容是 OUTSIDE-THE-ROOT。", t=tl(S(2)), mark=lidx(S(2), '/static/.env', '/static/link.txt', '/static/sub/ ', '/static/nested/ '), done=lidx(S(2), '/static/a.txt', '/static/index.html', '/static/sub  '), kv=KV([['点文件 .env', '200,会被直接提供'], ['指向根外的符号链接', '被跟随,200'], ['没有 index 的目录', '404 + 空的目录页']], ['点文件 .env'])),
    step("10 种路径穿越写法全部是 404:/static/../secret.txt、..%2f、%2e%2e/、%2e%2e%2f、双重编码 ..%252f、sub/../../、反斜杠、%00、//etc/passwd、sub/..%2f..%2f——Go 的 http.Dir.Open 会把请求路径先 path.Clean 成以 / 为根的路径,所以 .. 越不出根目录;注意这只防“路径里的 ..”,防不了符号链接。", t=tl(S(3)), mark=lidx(S(3), '..%2fsecret.txt', '%2e%2e%2fsecret.txt', '%252f'), done=lidx(S(3), '/static/../secret.txt', '..\\secret.txt', '/static/%00', '//etc/passwd'), b=bars([['404(未越出根目录)', 10, '10 / 10'], ['读到根目录之外的文件', 0, '0 / 10']], 10, done=[0], mark=[1]), kv=KV([['路径里的 ..', '一律被 Clean 掉'], ['符号链接', '不防(http.Dir 文档说明会跟随)']], ['符号链接'])),
    step("目录列表:Static(\"/nolist\") 对没有 index 的目录 /nolist/sub/ 返回 404 和一个空的 <pre></pre> 页(状态码来自前面的 WriteHeader(404),目录页没有再设状态);StaticFS(\"/list\", http.Dir(…)) 与 StaticFS(\"/list2\", gin.Dir(…, true)) 返回 200 和真实列表(<a href=\"b.txt\">b.txt</a>);嵌套目录也能列出子目录 deep/。", t=tl(S(4)), mark=lidx(S(4), '/nolist/sub/', '/nolist/nested/'), done=lidx(S(4), '/list/sub/', '/list2/sub/', '/list/nested/'), kv=KV([['Static', '不列目录:404 + 空页'], ['StaticFS(http.Dir)', '列目录'], ['gin.Dir(root, true)', '列目录']], ['Static'])),
    step("缓存头由 http.ServeContent 决定:响应有 Last-Modified、Accept-Ranges: bytes、Content-Length,没有 ETag、没有 Cache-Control;带 If-Modified-Since 等于 Last-Modified → 304 空正文,带更早的日期 → 200 全文;HEAD → 200、没有正文但 Content-Length=7;Content-Type 按扩展名(.txt → text/plain; charset=utf-8,.html → text/html; charset=utf-8),没有扩展名的文本文件靠嗅探前 512 字节也得到 text/plain;POST → 404(只注册了 GET 与 HEAD)。", t=tl(S(5)), mark=lidx(S(5), 'ETag=""', '带 If-Modified-Since=Last-Modified → 304', 'POST a.txt'), done=lidx(S(5), '带更早的 If-Modified-Since', 'HEAD a.txt', '无扩展名 noext', 'page.html'), kv=KV([['Last-Modified', '有;If-Modified-Since → 304'], ['ETag / Cache-Control', '都没有,要自己加'], ['Content-Type', '扩展名优先,否则嗅探']], ['ETag / Cache-Control'])),
    step("Static(\"/\", …) 与其它路由共存:先 GET /ping 再 Static(\"/\") → panic:catch-all wildcard '*filepath' … conflicts with existing path segment 'ping';先 Static(\"/\") 再 GET /ping → panic:'/ping' … conflicts with existing wildcard '/*filepath';Static(\"/assets\") 与 GET /ping 并存没问题;但 Static(\"/assets\") 再 GET /assets/x → panic(同一前缀下 catch-all 与静态冲突);StaticFile / Static 的路径里不能写参数或通配符(panic: URL parameters can not be used …)。", t=tl(S(6)), mark=lidx(S(6), 'panic'), done=lidx(S(6), '注册成功'), kv=KV([['Static("/")', '与任何同级路由冲突'], ['Static("/assets")', '只与 /assets/* 下的路由冲突'], ['参数 / 通配符', 'Static、StaticFile 的路径里禁止']], ['Static("/")'])),
]
A = mkartn('n39', 39, 'Gin,静态文件,Static,StaticFS,目录列表,路径穿越,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测静态文件服务:Static 不列目录(没有 index 的目录是 404 加空页);点文件 .env 和指向根目录之外的符号链接都会被直接提供;10 种路径穿越写法全部 404;Last-Modified 有而 ETag 没有;Static("/") 与同级路由冲突会 panic。',
    'r.Static("/static", "./public") 一行就能发布目录,但它到底提供什么、不提供什么?点文件会不会泄漏?路径穿越拦不拦得住?符号链接呢?这篇用原始 TCP 请求把 Static 的行为逐项试出来。',
    [('200', '/static/.env(点文件)的状态码:内容被直接返回'), ('200', '指向根目录之外的符号链接 /static/link.txt 的状态码'), ('10 / 10', '10 种路径穿越写法全部是 404')],
    [('Static 做了什么', '<p><code>Static</code> 是对标准库 <code>http.FileServer</code> 的薄封装:用 <code>Dir(root, false)</code> 禁止列目录,去掉 URL 前缀后交给 FileServer,打不开的文件走 Gin 的 NoRoute。所以缓存头、Range、If-Modified-Since、Content-Type 嗅探都是标准库的行为。</p>'),
     ('不会替你过滤什么', '<p>目录下的<b>所有</b>文件都会被提供,包括 <code>.env</code> 这样的点文件;符号链接会被跟随,即使它指向根目录之外(<code>http.Dir</code> 文档明确说了这一点)。把 <code>Static</code> 的根目录指到项目根目录是最常见的泄漏源码和配置的方式。只放需要公开的文件,并且别在里面放符号链接。</p>'),
     ('路径穿越', '<p>10 种穿越写法(<code>..</code>、编码的 <code>%2e%2e%2f</code>、双重编码、反斜杠、NUL、多层 <code>../</code>)全部得到 404:标准库先把路径 Clean 成以根为起点的绝对路径,<code>..</code> 无法越出根。这只限于路径本身,不包括符号链接,也不包括你自己用 <code>c.File</code> 拼接的路径(见后面的文章)。</p>'),
     ('目录与列表', '<p>没有 index.html 的目录,<code>Static</code> 返回 404 加一个空的目录页(它先把状态设成 404,目录页再没改);想列目录用 <code>StaticFS</code> 配 <code>http.Dir</code> 或 <code>gin.Dir(root, true)</code>,但这几乎总是不该在生产里做的事。</p>'),
     ('缓存与条件请求', '<p>响应带 <code>Last-Modified</code> 和 <code>Accept-Ranges</code>,支持 <code>If-Modified-Since</code> 返回 304,但没有 <code>ETag</code> 也没有 <code>Cache-Control</code>——浏览器会启发式缓存。需要长缓存(带 hash 的文件名)就要自己用中间件加 <code>Cache-Control</code>。</p>'),
     ('与其它路由的冲突', '<p><code>Static("/", dir)</code> 注册的是根上的 catch-all,与同级的任何路由都冲突(先后顺序都会 panic)。通常用 <code>Static("/assets", …)</code> 这样的前缀,或者把单页应用的入口交给 <code>NoRoute</code>。</p>')],
    steps,
    [ENV_N_GIN + '。请求大多是原始 TCP 手写的请求行(避免客户端提前改写路径),缓存头实验用 http.Transport.RoundTrip;测试目录是实验时在程序目录里创建的小文件,符号链接指向 ../secret.txt;每种情形各一次',
     '没有验证:Windows 路径(反斜杠、保留设备名如 CON);大小写不敏感的文件系统(macOS 默认,是在 macOS 上测的,但没有专门测大小写);http.FileServer 对 ../ 的处理在不同 Go 版本里的差异;embed.FS 与 StaticFS 组合;URL 里的 %00 是否在更底层被拒绝'],
    '静态文件')
